function t(){const x=Math.max(0,Math.floor((L-new Date())/1000));$('d').textContent=Math.floor(x/86400);$('h').textContent=Math.floor(x%86400/3600);$('m').textContent=Math.floor(x%3600/60);$('s').textContent=x%60}t();setInterval(t,1000);
const P=[["Fold desk","Wall-mounted desk that folds flat to 9 cm. £240.",'<rect x="20" y="20" width="60" height="44" fill="none" stroke="#1B4332" stroke-width="5"/><path d="M20 64l20 18h40l-20-18" fill="#FFB4A2" stroke="#1B4332" stroke-width="4"/>'],["Stack stool","Stools that stack six high and double as side tables. £65.",'<rect x="24" y="30" width="52" height="10" fill="#FFB4A2" stroke="#1B4332" stroke-width="4"/><path d="M30 40l-6 44M70 40l6 44M34 62h32" stroke="#1B4332" stroke-width="5"/>'],["Nook shelf","Corner shelf that turns dead space into storage. £120.",'<path d="M20 16v68h60" fill="none" stroke="#1B4332" stroke-width="5"/><path d="M20 38h40M20 60h50" stroke="#1B4332" stroke-width="5"/><rect x="30" y="26" width="10" height="12" fill="#FFB4A2"/><circle cx="52" cy="52" r="7" fill="#FFB4A2"/>']];let pi=0;
function pk(){$('pc').innerHTML=P.map((p,i)=>`<button type="button" aria-pressed="${i===pi}" data-i="${i}" aria-label="${p[0]}"><svg viewBox="0 0 100 100" aria-hidden="true">${p[2]}</svg></button>`).join('');$('pa').innerHTML=`<svg viewBox="0 0 100 100" aria-hidden="true">${P[pi][2]}</svg>`;$('pn').textContent=P[pi][0];$('pd').textContent=P[pi][1]}
